'use strict';const AlbumCommentsModalHead=({metadata:a})=>`
    <div class="modal fade" id="propalbumphotocomment${a.id}" tabindex="-1" role="dialog" aria-labelledby="label${a.id}" aria-hidden="true">
        <div class="modal-dialog modal-lg modal-dialog-scrollable" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title" id="commentModalLabel">
                        <div id="propalbumphotocomment${a.id}">
                            <img loading="lazy" src="${encodeURI(a.thumbnailUrlCentered)}" width="100" height="100" onError="Util.errorImg(this,\\'${a.title}\\',100)">
                        </div>Comments for ${a.fileName}
                    </h5>
                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                </div>
                <div class="modal-body">
                    <input type="hidden" id="currentCommentId${a.id}" name="currentCommentId${a.id}">
                    <ul class="list-group" id="commentList${a.id}">
`,AlbumComment=({commentId:a,commentText:d,userId:b,commentUserId:c,username:e})=>`
    <li class="list-group-item${c===b?" list-group-item-secondary":""}" id="comment${a}">
        <span id="commentcontainer${a}">
            <p id="commentcontent${a}">${d}</p>
            ${c===b?`<small>${e}<span style="float: right"><a href="#" id="deletecomment${a}"><span class="bi-trash"></span></a>&nbsp;&nbsp;<a href="#" id="editcomment${a}"><span class="bi-pencil"></span></a></span></small>`:""}
        </span>
        <span id="textareacontainer${a}"></span>
    </li>
`,AlbumCommentsModalFooter=({metadata:a})=>`
                    </ul>
                </div>
                <div class="modal-footer">
                    <textarea class="form-control" id="commentText${a.id}" rows="2"></textarea>
                    <button type="button" class="btn btn-primary" id="saveCommentMetadata${a.id}">Save</button>
                    <button type="button" class="btn btn-primary" id="updateCommentMetadata${a.id}">Update</button>
                    <button type="button" class="btn btn-secondary" id="dismissModalCommentMetadata${a.id}" data-bs-dismiss="modal">Cancel</button>
                    <button type="button" class="btn btn-secondary" id="cancelEditCommentMetadata${a.id}" data-bs-dismiss="modal">Cancel</button>
                </div>
            </div>
        </div>
    </div>
`;

